from pathlib import Path

import pytest


def read_public(path: str) -> str:
    """Return the text of the file at ``path`` inside the ``notes`` directory.

    ``path`` is interpreted relative to the ``notes`` directory, relative to
    the current working directory. It may contain ``..`` segments as long as
    the resolved location stays inside ``notes``. Absolute paths, paths that
    leave ``notes`` (including through symlinks), missing files, directories,
    and unreadable files all yield an empty string.
    """
    if "\x00" in path or Path(path).is_absolute():
        return ""
    root = (Path.cwd() / "notes").resolve()
    try:
        target = (root / path).resolve()
        if not target.is_relative_to(root):
            return ""
        return target.read_text(encoding="utf-8")
    except (OSError, ValueError):
        return ""


@pytest.fixture
def layout(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    """Create notes/ with a.txt and sub/b.txt, plus secret.txt outside notes/."""
    monkeypatch.chdir(tmp_path)
    notes = tmp_path / "notes"
    (notes / "sub").mkdir(parents=True)
    (notes / "a.txt").write_text("alpha", encoding="utf-8")
    (notes / "sub" / "b.txt").write_text("beta", encoding="utf-8")
    (tmp_path / "secret.txt").write_text("secret", encoding="utf-8")
    return tmp_path


def test_reads_file_in_notes(layout: Path) -> None:
    assert read_public("a.txt") == "alpha"


def test_reads_file_in_subdirectory(layout: Path) -> None:
    assert read_public("sub/b.txt") == "beta"


def test_dotdot_that_stays_inside_notes_is_allowed(layout: Path) -> None:
    assert read_public("sub/../a.txt") == "alpha"


def test_dotdot_escape_returns_empty(layout: Path) -> None:
    assert read_public("../secret.txt") == ""


def test_deep_dotdot_escape_returns_empty(layout: Path) -> None:
    assert read_public("sub/../../secret.txt") == ""


def test_absolute_path_returns_empty(layout: Path) -> None:
    assert read_public(str(layout / "secret.txt")) == ""


def test_missing_file_returns_empty(layout: Path) -> None:
    assert read_public("nope.txt") == ""


def test_directory_returns_empty(layout: Path) -> None:
    assert read_public("sub") == ""


def test_null_byte_returns_empty(layout: Path) -> None:
    assert read_public("a.txt\x00") == ""


def test_symlink_escaping_notes_returns_empty(layout: Path) -> None:
    (layout / "notes" / "link.txt").symlink_to(layout / "secret.txt")
    assert read_public("link.txt") == ""
